using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using System.ComponentModel;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

builder.Services.AddSingleton<NoteService>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var noteService = host.Services.GetRequiredService<NoteService>();

// Define tools available to the agent
var tools = new AITool[]
{
    AIFunctionFactory.Create(
        (string query) =>
        {
            Console.WriteLine($"  [Searching web for: \"{query}\"]");
            // Simulated web search results — replace with a real search API
            return query.ToLowerInvariant() switch
            {
                var q when q.Contains("climate") => """
                    1. NASA: Global temperatures have risen 1.1°C since pre-industrial times.
                    2. IPCC AR6: Net-zero emissions by 2050 needed to limit warming to 1.5°C.
                    3. NOAA: 2024 was the warmest year on record globally.
                    """,
                var q when q.Contains("ai") || q.Contains("artificial intelligence") => """
                    1. Stanford HAI: AI adoption in enterprise grew 60% year-over-year in 2025.
                    2. Nature: Transformer architectures remain dominant in NLP and vision.
                    3. MIT Tech Review: Agentic AI workflows are the top trend in 2026.
                    """,
                _ => $"""
                    1. Wikipedia: Overview of "{query}" — a broad topic with multiple subtopics.
                    2. Recent study (2025): New findings related to {query} published in Nature.
                    3. News: Public interest in {query} has increased 30% this year.
                    """
            };
        },
        "search_web",
        "Searches the web for information on a given query and returns relevant results."),

    AIFunctionFactory.Create(
        ([Description("Title or key for the note")] string title,
         [Description("Content of the note to save")] string content) =>
        {
            noteService.AddNote(title, content);
            Console.WriteLine($"  [Note saved: \"{title}\"]");
            return $"Note '{title}' saved successfully.";
        },
        "take_note",
        "Saves a research note with a title and content for later reference."),

    AIFunctionFactory.Create(
        () =>
        {
            var notes = noteService.GetAllNotes();
            return notes.Count == 0
                ? "No notes taken yet."
                : string.Join("\n\n", notes.Select(n => $"## {n.Title}\n{n.Content}"));
        },
        "get_notes",
        "Retrieves all research notes taken so far."),
};

// Configure the agent
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information (use multiple searches to cover different angles).
        2. Taking notes on key findings as you go.
        3. After gathering enough information, retrieve your notes and produce a clear, well-organized summary.

        Always take notes on important findings before producing your final summary.
        Be thorough but concise in your final output.
        """,
    Tools = tools,
};

// Get the research topic
Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research (or press Enter for 'AI trends in 2026'): ");
var topic = Console.ReadLine();
if (string.IsNullOrWhiteSpace(topic))
    topic = "AI trends in 2026";

Console.WriteLine($"\nResearching: {topic}\n");

// Run the agent
var messages = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

string? finalResponse = null;
await foreach (var message in agent.InvokeStreamingAsync(messages, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        finalResponse = message.Text;
    }
}

Console.WriteLine("\n--- Research Summary ---\n");
Console.WriteLine(finalResponse ?? "No summary generated.");

Console.WriteLine("\n--- Notes Collected ---\n");
foreach (var note in noteService.GetAllNotes())
{
    Console.WriteLine($"[{note.Title}]");
    Console.WriteLine($"  {note.Content}\n");
}

// Note-taking service
public sealed class NoteService
{
    private readonly List<ResearchNote> _notes = [];

    public void AddNote(string title, string content) =>
        _notes.Add(new ResearchNote(title, content));

    public IReadOnlyList<ResearchNote> GetAllNotes() => _notes.AsReadOnly();

    public int Count => _notes.Count;
}

public sealed record ResearchNote(string Title, string Content);

